describe('Account', () => {
  let account;
  beforeEach(() => { account = new Account(100); });   // Arrange

  it('reduces the balance when 30 is withdrawn', () => {
    const ok = account.withdraw(30);                   // Act
    expect(ok).toBe(true);                             // Assert
    expect(account.balance).toBe(70);
  });
});

