// features/withdraw.feature
//   Scenario: withdraw within balance
//     Given an account with 100
//     When I withdraw 30
//     Then the balance should be 70

When('I withdraw {int}', function (amount) {              // Act
  this.ok = this.account.withdraw(amount);
});

Then('the balance should be {int}', function (expected) {  // Assert
  assert.equal(this.account.balance, expected);
});
